import { afterEach, expect, it, vi } from 'vitest'
import { createApp, nextTick } from 'vue'
import feedXML from '../lib/__fixtures__/feed.atom?raw'
import keysJSON from '../lib/__fixtures__/keys.json'
import { settings } from '../lib/settings'
import TimelineView from './TimelineView.vue'

afterEach(() => vi.unstubAllGlobals())

async function settle() {
  for (let i = 0; i < 10; i++) {
    await new Promise((r) => setTimeout(r, 0))
    await nextTick()
  }
}

it('renders the feed with verified signatures and own-post actions', async () => {
  // The fixture was generated by an amfeed at this base URL.
  settings.feedServer = 'http://localhost:8198'
  settings.token = 'test'
  settings.timeline = ''

  const fetchMock = vi.fn(async (url: string) => {
    if (url === 'http://localhost:8198/feed.atom') return new Response(feedXML)
    if (url === 'http://localhost:8198/atomic-keys') return Response.json(keysJSON)
    return new Response('not found', { status: 404 })
  })
  vi.stubGlobal('fetch', fetchMock)

  const el = document.createElement('div')
  const app = createApp(TimelineView)
  app.mount(el)
  await settle()

  const entries = el.querySelectorAll('article.entry')
  expect(entries).toHaveLength(5)
  expect(el.querySelector('.timeline-header h2')?.textContent).toBe("Fixture's Feed")
  expect(el.querySelectorAll('.sig.ok')).toHaveLength(5)
  expect(el.querySelectorAll('article.entry.deleted')).toHaveLength(1)
  expect(el.querySelector('.in-reply-to')?.textContent).toContain('http://localhost:8198/posts/1')
  expect(el.querySelector('.content em')?.textContent).toBe('content') // HTML rendered
  // Own posts get a delete button; tombstones get no actions.
  expect(el.querySelectorAll('button.danger')).toHaveLength(4)
  // Keys are fetched once, not per entry.
  expect(fetchMock.mock.calls.filter(([u]) => u.endsWith('atomic-keys'))).toHaveLength(1)

  app.unmount()
})

it('opens the reply box under the post and keeps the top box', async () => {
  settings.feedServer = 'http://localhost:8198'
  settings.token = 'test'
  settings.timeline = ''
  vi.stubGlobal(
    'fetch',
    vi.fn(async (url: string, init?: RequestInit) => {
      if (url === 'http://localhost:8198/feed.atom') return new Response(feedXML)
      if (url === 'http://localhost:8198/atomic-keys') return Response.json(keysJSON)
      if (url === 'http://localhost:8198/api/entries' && init?.method === 'POST')
        return Response.json({ id: 'x' }, { status: 201 })
      return new Response('not found', { status: 404 })
    }),
  )
  const el = document.createElement('div')
  const app = createApp(TimelineView)
  app.mount(el)
  await settle()
  const forms = () => [...el.querySelectorAll('form.compose')].map((f) => f.className)
  const button = (root: ParentNode, text: string) =>
    [...root.querySelectorAll('button')].filter((b) => b.textContent?.trim() === text)
  const top = ['compose']
  const withReply = ['compose', 'compose reply']
  expect(forms()).toEqual(top)

  // The reply box opens under the post, after its card.
  button(el, 'Reply')[0].click()
  await settle()
  expect(forms()).toEqual(withReply)
  expect(el.querySelector('article.entry + form.compose.reply')).not.toBeNull()

  const reply = el.querySelector('form.compose.reply') as HTMLFormElement
  const ta = reply.querySelector('textarea')!
  ta.value = 'hi'
  ta.dispatchEvent(new Event('input'))
  await settle()
  reply.dispatchEvent(new Event('submit'))
  await settle()
  expect(forms()).toEqual(top)

  button(el, 'Reply')[1].click()
  await settle()
  expect(forms()).toEqual(withReply)
  button(el.querySelector('form.compose.reply')!, 'Cancel')[0].click()
  await settle()
  expect(forms()).toEqual(top)

  app.unmount()
})
